(26, 24, 'Summer Uniforms', 'summer-uniforms', '', 'Shivam Uniforms (established in Faridabad) aur Shivam Uniforms/Enterprises manufacturers ke taur par school aur corporate uniforms ki wide range provide karte hain. Inke summer school uniform collection ka overview niche diya gaya hai:\r\n\r\nSummer Shirts (Half Sleeves): Light-colored aur', 'Summer Uniforms', 'Shivam Uniforms (established in Faridabad) aur Shivam Uniforms/Enterprises manufacturers ke taur par school aur corporate uniforms ki wide range provide karte h', '', 'Active', '1790576440', ''),
(27, 24, 'Winter Uniforms', 'winter-uniforms', '', 'Sardi ke dinon mein poori warmth aur comfort dene ke liye high-quality woolen aur heavy-blend fabrics se taiyar ki gayi winter uniform. Isme full-sleeve shirts, warm trousers aur skirts shamil hain jo durable aur long-lasting hain.', 'Winter Uniforms', 'Sardi ke dinon mein poori warmth aur comfort dene ke liye high-quality woolen aur heavy-blend fabrics se taiyar ki gayi winter uniform. Isme full-sleeve shirts,', '', 'Active', '1790576522', ''),
(28, 24, 'School Uniform Coats', 'school-uniform-coats', '', 'Premium finish aur elegant look ke liye high-grade tailoring ke sath banaye gaye school blazers aur coats. Yeh thand ke mausam mein formal aur smart appearance dete hain, jo school standards ke bilkul anuroop hain.', 'School Uniform Coats', 'Premium finish aur elegant look ke liye high-grade tailoring ke sath banaye gaye school blazers aur coats. Yeh thand ke mausam mein formal aur smart appearance', '', 'Active', '1790576538', ''),
(29, 24, 'School Tracksuits', 'school-tracksuits', '', 'Sports aur Physical Education (P.E.) classes ke liye flexible aur stretchable fabric se bane stylish tracksuits. Yeh students ko running aur sports activities ke dauran complete ease of movement aur comfort dete hain.', 'School Tracksuits', 'Sports aur Physical Education (P.E.) classes ke liye flexible aur stretchable fabric se bane stylish tracksuits. Yeh students ko running aur sports activities k', '', 'Active', '1790576556', ''),
(30, 24, 'School Jackets', 'school-jackets', '', 'Halki sardi aur rainy seasons ke liye comfortable, wind-resistant, aur stylish school jackets. Inme durable zippers aur clean stitching di gayi hai jo daily school wear ke liye ekdam perfect hain.', 'School Jackets', 'Halki sardi aur rainy seasons ke liye comfortable, wind-resistant, aur stylish school jackets. Inme durable zippers aur clean stitching di gayi hai jo daily sch', '', 'Active', '1790576577', ''),
(31, 25, 'Corporate T-Shirts & Shirts', 'corporate-t-shirts-shirts', '', 'Office staff aur professionals ke liye premium cotton-blend fabric se bani formal shirts aur casual corporate T-shirts. Yeh clean look, sharp fitting aur crease-resistant finish ke sath aati hain jo professional identity ko enhance karti hain.', 'Corporate T-Shirts & Shirts', 'Office staff aur professionals ke liye premium cotton-blend fabric se bani formal shirts aur casual corporate T-shirts. Yeh clean look, sharp fitting aur crease', '', 'Active', '1790576600', ''),
(32, 25, 'Corporate Pants', 'corporate-pants', '', 'Professional meetings aur daily office wear ke liye expertly tailored comfortable trousers. Yeh durable fabric aur professional cuts ke sath aate hain jo lambe working hours mein bhi poora comfort provide karte hain.', 'Corporate Pants', 'Professional meetings aur daily office wear ke liye expertly tailored comfortable trousers. Yeh durable fabric aur professional cuts ke sath aate hain jo lambe', '', 'Active', '1790576619', ''),
(33, 25, 'Corporate Hoodies', 'corporate-hoodies', '', 'Casual Fridays ya winter corporate branding ke liye soft fleece fabric aur modern fit se bane branded hoodies. Yeh team unity aur comfortable casual style ke liye best option hain.', 'Corporate Hoodies', 'Casual Fridays ya winter corporate branding ke liye soft fleece fabric aur modern fit se bane branded hoodies. Yeh team unity aur comfortable casual style ke li', '', 'Active', '1790576635', ''),
(34, 26, 'Industrial T-Shirts', 'industrial-t-shirts', '', 'Factories, workshops, aur heavy-duty environments ke liye rugged aur tough cotton-rich industrial T-shirts. Yeh paseene aur rough use koasani se jhel sakti hain aur workers ko active rakhti hain.', 'Industrial T-Shirts', 'Factories, workshops, aur heavy-duty environments ke liye rugged aur tough cotton-rich industrial T-shirts. Yeh paseene aur rough use koasani se jhel sakti hain', '', 'Active', '1790576663', ''),
(35, 26, 'Industrial Shirts', 'industrial-shirts', '', 'Heavy industrial work ke liye tough stitching aur tear-resistant fabric se bani durable shirts. Inme utility pockets aur double-stitched seams diye gaye hain jo harsh working conditions ke liye ideal hain.', 'Industrial Shirts', 'Heavy industrial work ke liye tough stitching aur tear-resistant fabric se bani durable shirts. Inme utility pockets aur double-stitched seams diye gaye hain jo', '', 'Active', '1790576675', ''),
(36, 26, 'Industrial Jackets', 'industrial-jackets', '', 'Factory floors aur outdoor industrial sites ke liye safety aur warmth dene wali heavy-duty protective jackets. Yeh high durability aur wind-proof material ke sath aati hain.', 'Industrial Jackets', 'Factory floors aur outdoor industrial sites ke liye safety aur warmth dene wali heavy-duty protective jackets. Yeh high durability aur wind-proof material ke sa', '', 'Active', '1790576693', ''),
(37, 27, 'Aprons', 'aprons', '', 'Restaurants, cafes, aur kitchens ke liye stain-resistant aur durable fabric se bane adjustable aprons. Yeh staff ko clean look dete hain aur daily kitchen spills se protection provide karte hain.', 'Aprons', 'Restaurants, cafes, aur kitchens ke liye stain-resistant aur durable fabric se bane adjustable aprons. Yeh staff ko clean look dete hain aur daily kitchen spill', '', 'Active', '1790576715', ''),
(38, 27, 'Chef Caps', 'chef-caps', '', 'Professional chefs aur kitchen staff ke liye breathable, lightweight, aur hygienic chef caps. Yeh cooking ke dauran hair-falling se bachate hain aur professional kitchen standards ko maintain karte hain.', 'Chef Caps', 'Professional chefs aur kitchen staff ke liye breathable, lightweight, aur hygienic chef caps. Yeh cooking ke dauran hair-falling se bachate hain aur professiona', '', 'Active', '1790576729', ''),
(39, 27, 'Waiter Coats', 'waiter-coats', '', 'Hotel aur restaurant service staff ke liye elegant aur smart styling ke sath design kiye gaye waiter coats/vests. Yeh hospitality environment ko ek premium aur sophisticated look dete hain.', 'Waiter Coats', 'Hotel aur restaurant service staff ke liye elegant aur smart styling ke sath design kiye gaye waiter coats/vests. Yeh hospitality environment ko ek premium aur', '', 'Active', '1790576748', ''),
(40, 27, 'Chef Coats', 'chef-coats', '', 'Master chefs ke liye double-breasted design, high-grade heat-resistant cotton fabric, aur comfortable fitting ke sath bani professional chef jackets. Yeh kitchen ki garmi mein bhi comfortable rehti hain.', 'Chef Coats', 'Master chefs ke liye double-breasted design, high-grade heat-resistant cotton fabric, aur comfortable fitting ke sath bani professional chef jackets. Yeh kitche', '', 'Active', '1790576767', ''),
(41, 28, 'Security Uniforms', 'security-uniforms', '', 'Guards aur security personnel ke liye tough, authoritative, aur weather-resistant fabric se taiyar ki gayi security uniforms. Isme durable shirts, trousers, aur matching accessories shamil hain jo day-and-night shifts mein maximum durability aur professional presence deti hain.', 'Security Uniforms', 'Guards aur security personnel ke liye tough, authoritative, aur weather-resistant fabric se taiyar ki gayi security uniforms. Isme durable shirts, trousers, aur', '', 'Active', '1790576781', ''),
(42, 30, 'Sustainable polo', 'sustainable-polo', '', 'Discover our Sustainable Polo T-shirt, designed for everyday comfort, durability, and a professional look. Made with a focus on sustainable materials, it offers a comfortable fit and versatile style for corporate uniforms, staff apparel, and daily wear. Perfect for businesses looking for a smart, practical, and eco-conscious uniform solution', 'Sustainable polo', 'Discover our Sustainable Polo T-shirt, designed for everyday comfort, durability, and a professional look. Made with a focus on sustainable materials, it offers', '', 'Active', '1792647473', '');

